import { useFonts } from 'expo-font';
import { router, useNavigation } from 'expo-router';
import { useEffect, useRef } from 'react';
import { mixFonts } from './fonts';
import { Reported } from './report';
import Screen from './V86AppV101Home';

const SHOWN = 'V86AppV101Home';

export default function Preview() {
  const [ready, error] = useFonts(mixFonts);
  const navigation = useNavigation();
  const last = useRef(SHOWN);
  // Picking another frame in Figma brings the phone back here to show it,
  // even after tapping deep into prototype links.
  useEffect(() => {
    if (last.current === SHOWN) return;
    last.current = SHOWN;
    if (!navigation.isFocused() && router.canDismiss()) router.dismissTo('/');
  });
  return (
    <Reported screen="V86AppV101Home" fontsReady={ready} fontError={error}>
      {ready || error ? <Screen /> : null}
    </Reported>
  );
}
